PageCurrencyControl = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=PageCurrencyControl]");

        var defaultCurrency = app.Config.B2B.DefaultCurrency 
            ? app.Config.B2B.DefaultCurrency 
            : "EUR";

        var data = app.Config.B2B.Currencies 
            ? app.Config.B2B.Currencies 
            : ["USD", "EUR", "GBP"];

        $("[name=pageCurrencyDropdown]", container).kendoDropDownList({
            dataSource: data,
            index: data.indexOf(defaultCurrency),
            change:PageCurrencyControl.onChange
        }).data("kendoDropDownList");

        $(document).ready(() => {
            var hideComponentCurrencySelectors = function(root) {
                $(root || document).find("[name=currencyDropdown]").addBack("[name=currencyDropdown]").each(function() {
                    $(this).closest(".k-picker").hide();
                });
            };

            hideComponentCurrencySelectors(document);
            new MutationObserver(function(mutations) {
                mutations.forEach(function(mutation) {
                    mutation.addedNodes.forEach(function(node) {
                        if(node.nodeType === 1)
                            hideComponentCurrencySelectors(node);
                    });
                });
            }).observe(document.body, { childList: true, subtree: true });
        });
    },
    onChange: function(e) {
        var value = this.value();
        var dropdowns = $("[name=currencyDropdown]");
        dropdowns.each((i) => {
            var dropdown = $(dropdowns[i]).data("kendoDropDownList");
            dropdown.value(value);
            dropdown.trigger('change');
        });
    }
}
